package lk.ac.sliit.ridelink.ride.infrastructure.client.driver;
import lk.ac.sliit.ridelink.ride.application.dto.response.EligibleDriverData; import lk.ac.sliit.ridelink.ride.application.port.out.DriverAssignmentPort; import lk.ac.sliit.ridelink.ride.application.usecase.*; import lk.ac.sliit.ridelink.ride.domain.enums.VehicleType; import lk.ac.sliit.ridelink.ride.infrastructure.client.ClientSupport; import lk.ac.sliit.ridelink.ride.infrastructure.security.InternalServiceTokenProvider; import org.springframework.beans.factory.annotation.Qualifier; import org.springframework.core.ParameterizedTypeReference; import org.springframework.http.*; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.util.*;
@Component public class DriverServiceClient implements DriverAssignmentPort {private final RestClient client;private final InternalServiceTokenProvider tokens;public DriverServiceClient(@Qualifier("driverRestClient") RestClient c,InternalServiceTokenProvider t){client=c;tokens=t;}public List<EligibleDriverData> eligible(String area,VehicleType type){try{List<EligibleDriverData> out=client.get().uri(u->u.path("/api/v1/internal/drivers/eligible").queryParam("serviceArea",area).queryParam("vehicleType",type).build()).header(HttpHeaders.AUTHORIZATION,"Bearer "+tokens.token()).retrieve().onStatus(HttpStatusCode::isError,(q,r)->ClientSupport.status("Driver Service",r.getStatusCode())).body(new ParameterizedTypeReference<>(){});return out==null?List.of():out;}catch(ExternalServiceException e){throw e;}catch(RestClientException e){throw ClientSupport.failure("Driver Service",e);}}public void assign(UUID driver,UUID ride){try{client.put().uri("/api/v1/internal/drivers/{driver}/assignments/{ride}",driver,ride).header(HttpHeaders.AUTHORIZATION,"Bearer "+tokens.token()).retrieve().onStatus(HttpStatusCode::isError,(q,r)->ClientSupport.status("Driver Service",r.getStatusCode())).toBodilessEntity();}catch(ExternalServiceException e){throw e;}catch(RestClientException e){throw ClientSupport.failure("Driver Service",e);}}public void restore(UUID driver,UUID ride){try{client.delete().uri("/api/v1/internal/drivers/{driver}/assignments/{ride}",driver,ride).header(HttpHeaders.AUTHORIZATION,"Bearer "+tokens.token()).retrieve().onStatus(HttpStatusCode::isError,(q,r)->ClientSupport.status("Driver Service",r.getStatusCode())).toBodilessEntity();}catch(ExternalServiceException e){throw e;}catch(RestClientException e){throw ClientSupport.failure("Driver Service",e);}}}
